#!/usr/bin/env python3
"""Fail when a file outside the reviewed list can lower the `unsafe_code` lint.

`unsafe-policy.yml` compiles the workspace with `-Dunsafe-code`. A source
attribute that names `unsafe_code` inside `allow`, `expect` or `warn` overrides
that flag, whether the lint stands alone or among others, directly or through
`cfg_attr`, on one line or several; so would a manifest `[lints]` entry. This
check reads every workspace member (fuzz crates and `target` directories
aside), the root manifest and `.cargo/*.toml`, and lists each file that names
the lint anywhere except in a plain `forbid(...)` or `deny(...)` attribute (or
a `"forbid"`/`"deny"` manifest level). The list must equal `ALLOWED`.

    python3 .github/check-unsafe-allowlist.py          # check
    python3 .github/check-unsafe-allowlist.py --list   # print ALLOWED

Mentioning the lint in a comment also counts, so the check errs on the side
of a finding. It does not see code generated by procedural macros or build
scripts of dependencies.
"""

from __future__ import annotations

import re
import sys
import tomllib
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent

# Reviewed files that may lower `unsafe_code`; each documents its `SAFETY`.
ALLOWED = (
    "cargo-rullst/src/generators/footprint/process/macos.rs",
    "cargo-rullst/src/generators/footprint/process/windows.rs",
    "cargo-rullst/src/update/cache/windows_acl.rs",
    "cargo-rullst/src/update/project/permissions_unix.rs",
    "cargo-rullst/src/update/project/permissions_windows.rs",
    # The hot-reload `#[unsafe(no_mangle)]` router export of the example.
    "examples/blog/src/lib.rs",
    "rullst-core/src/radar.rs",
    "rullst-core/src/server/dylib_loader.rs",
)

SKIPPED_DIRECTORIES = {".git", "fuzz", "node_modules", "target"}
LINT = re.compile(r"\bunsafe[_-]code\b")
# Also the `-Aunsafe-code` form of a rustflags entry.
MANIFEST_LINT = re.compile(r"unsafe[_-]code\b")
ATTRIBUTE_START = re.compile(r"#\s*!?\s*\[")
STRICT_ATTRIBUTE = re.compile(r"#\s*!?\s*\[\s*(?:forbid|deny)\s*\(")
LOWERING_WORD = re.compile(r"\b(?:allow|expect|warn|cfg_attr)\b")
STRICT_LEVEL = re.compile(r"[\"'](?:forbid|deny)[\"']")


def attribute_spans(text: str) -> list[tuple[int, int]]:
    """The `(start, end)` of each `#[...]` or `#![...]`, brackets balanced."""
    spans = []
    for match in ATTRIBUTE_START.finditer(text):
        depth = 0
        for index in range(match.end() - 1, len(text)):
            if text[index] == "[":
                depth += 1
            elif text[index] == "]":
                depth -= 1
                if depth == 0:
                    spans.append((match.start(), index + 1))
                    break
        else:
            # An unclosed attribute runs to the end of the file.
            spans.append((match.start(), len(text)))
    return spans


def rust_lowers_lint(text: str) -> bool:
    """Whether Rust source names `unsafe_code` other than to forbid or deny it."""
    spans = attribute_spans(text)
    for occurrence in LINT.finditer(text):
        enclosing = [
            text[start:end] for start, end in spans if start <= occurrence.start() < end
        ]
        if not enclosing:
            return True
        for attribute in enclosing:
            if not STRICT_ATTRIBUTE.match(attribute) or LOWERING_WORD.search(attribute):
                return True
    return False


def toml_lowers_lint(text: str) -> bool:
    """Whether a manifest or Cargo configuration sets `unsafe_code` below deny."""
    return any(
        MANIFEST_LINT.search(line)
        and (not STRICT_LEVEL.search(line) or LOWERING_WORD.search(line))
        for line in text.splitlines()
    )


def member_directories(root: Path) -> list[Path]:
    manifest = tomllib.loads((root / "Cargo.toml").read_text(encoding="utf-8"))
    directories = []
    for member in manifest.get("workspace", {}).get("members", []):
        directories.extend(sorted(path for path in root.glob(member) if path.is_dir()))
    return directories


def candidate_files(root: Path) -> list[Path]:
    files = [root / "Cargo.toml", *sorted((root / ".cargo").glob("*.toml"))]
    for directory in member_directories(root):
        stack = [directory]
        while stack:
            current = stack.pop()
            for entry in sorted(current.iterdir()):
                if entry.is_symlink():
                    continue
                if entry.is_dir():
                    if entry.name not in SKIPPED_DIRECTORIES:
                        stack.append(entry)
                elif entry.suffix == ".rs" or entry.name == "Cargo.toml":
                    files.append(entry)
    return files


def lowering_files(root: Path) -> list[str]:
    found = set()
    for path in candidate_files(root):
        if not path.is_file():
            continue
        text = path.read_text(encoding="utf-8", errors="replace")
        lowers = rust_lowers_lint(text) if path.suffix == ".rs" else toml_lowers_lint(text)
        if lowers:
            found.add(path.relative_to(root).as_posix())
    return sorted(found)


def main(arguments: list[str]) -> int:
    if arguments == ["--list"]:
        print("\n".join(ALLOWED))
        return 0
    if arguments:
        print("usage: check-unsafe-allowlist.py [--list]", file=sys.stderr)
        return 2
    actual = lowering_files(ROOT)
    expected = sorted(ALLOWED)
    if actual == expected:
        print(f"unsafe_code is lowered only in the {len(expected)} reviewed files.")
        return 0
    print("The reviewed unsafe exception allowlist changed:")
    for path in sorted(set(actual) - set(expected)):
        print(f"  not reviewed: {path}")
    for path in sorted(set(expected) - set(actual)):
        print(f"  listed but no longer lowering the lint: {path}")
    return 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
